const test=require('node:test'),assert=require('node:assert/strict'),{runAgent}=require('../src/agent.cjs');
test('identical failing tool calls stop before exhausting the whole agent loop',async()=>{let requests=0;await assert.rejects(runAgent({prompt:'작업 폴더 확인',settings:{workspace:'D:/synthetic'},signal:new AbortController().signal,send:()=>{},execute:async()=>{throw Error('Synthetic unavailable service');},request:async()=>({output:[{type:'function_call',name:'list_files',arguments:'{}',call_id:String(++requests)}]})}),/같은 도구 오류가 반복/);assert.equal(requests,3);});
test('successful observation clears the consecutive-error count',async()=>{let requests=0;const result=await runAgent({prompt:'작업 폴더 확인',settings:{workspace:'D:/synthetic'},signal:new AbortController().signal,send:()=>{},execute:async()=>{if(requests===3)return [];throw Error('Synthetic unavailable service');},request:async()=>({output:++requests===6?[{type:'message',content:[{type:'output_text',text:'확인 범위 보고'}]}]:[{type:'function_call',name:'list_files',arguments:'{}',call_id:String(requests)}]})});assert.equal(result,'확인 범위 보고');});
